S=/private/tmp/claude-501/-Users-korbi-Documents-coding-isar-labs-ehl/9fce6d6a-c487-47a3-9e99-3f4ee4ca7b5b/scratchpad; python3 - <<EOF
import json
d=json.load(open("$S/lb.json"))
B={str(b["id"]):b for b in d["benchmarks"]}
ms=sorted(d["models"],key=lambda m:-(m.get("index") or 0))
for m in ms[:30]:
    print(f'{m["name"][:34]:34} {m.get("kind","")[:22]:22} base={str(m.get("base_model"))[:26]:26} idx={m.get("index")} lat={m.get("latency")} ece={m.get("ece")} brier={m.get("brier")}')
print()
for m in ms:
    if "qwen" in (m["name"]+str(m.get("base_model"))).lower() and m["engine"]!="clef": print("QWEN-ish:",m["name"],m.get("kind"),m.get("index"),m.get("latency"))
rel=[b for b in d["benchmarks"] if any(w in (b["name"]+b["explainer"]).lower() for w in ["web","page","link","document","relevan","tool","retriev","screenshot","image","ui","click","navigat"])]
names={"Clef","Clef-flash"}
for b in rel:
    row={m["name"]:m["scores"].get(str(b["id"])) for m in ms if m["name"] in names}
    best=max(((m["scores"].get(str(b["id"])) or -1,m["name"]) for m in ms))
    print(b["id"],b["name"],b["metric"],"chance",b.get("chance"),row,"best",best,"|",b["explainer"][:150])
EOF

