import sys, json, urllib.request, collections, re
T=sys.argv[1]
def events(r):
    req=urllib.request.Request(f"https://ehl-challenge.atira.ai/v1/runs/{r}/logs.jsonl",headers={"x-api-key":T,"User-Agent":"rfq-analysis"})
    raw=urllib.request.urlopen(req,timeout=90).read().decode()
    evs=[]
    for l in raw.splitlines():
        if not l.strip(): continue
        row=json.loads(l)
