import sys, json, urllib.request, collections
T=sys.argv[1]
def fetch(r):
    req=urllib.request.Request(f"https://ehl-challenge.atira.ai/v1/runs/{r}/llm-calls?limit=2000",headers={"x-api-key":T,"User-Agent":"rfq-analysis"})
    return json.load(urllib.request.urlopen(req,timeout=90))
for r in ["run_5ec3ef02a134d258","run_e0c6871f8b2222c8","run_fef81fa10373c7ee","run_f0fadd6cb4e855ce"]:
    d=fetch(r); c=d["calls"]
    statuses=collections.Counter(x["status"] for x in c)
    # candidate hedge pairs: same total prompt tokens, second starts 10-40 s after first and before first ended (+tolerance)
    tot=lambda x:x["input_tokens"]+(x["cache_read_tokens"] or 0)
    pairs=[]
    for i,a in enumerate(c):
        for b in c[i+1:]:
            if b["at"]-a["at"]>45000: break
            if abs(tot(a)-tot(b))<=2 and 9000<=b["at"]-a["at"]<=45000 and b["at"]<a["at"]+a["latency_ms"]+500:
                pairs.append((a,b))
    print(r, "statuses",dict(statuses), "hedge-like pairs",len(pairs))
    for a,b in pairs[:6]:
        print(f"   first lat {a['latency_ms']/1000:.1f}s out {a['output_tokens']} ${a['cost_micro_usd']/1e6:.5f} | twin +{(b['at']-a['at'])/1000:.1f}s lat {b['latency_ms']/1000:.1f}s out {b['output_tokens']} ${b['cost_micro_usd']/1e6:.5f} status {b['status']}")
EOF

