from pathlib import Path
spec = importlib.util.spec_from_file_location("r", "dev/eval/extract_replay.py"); r = importlib.util.module_from_spec(spec); spec.loader.exec_module(r)
def load(v):
    d = collections.defaultdict(list)
    for p in sorted(Path(f"dev/runs/replay/{v}").glob("*.json")):
        d[p.name.rsplit(".", 2)[0]].append(json.loads(p.read_text()))
    return d
base, trim = load("base"), load("trim")
def diff(a, b, path=""):
    out = []
    if isinstance(a, dict) and isinstance(b, dict):
        for k in sorted(set(a) | set(b)): out += diff(a.get(k), b.get(k), f"{path}.{k}")
    elif isinstance(a, list) and isinstance(b, list) and len(a) == len(b):
        for i, (x, y) in enumerate(zip(a, b)): out += diff(x, y, f"{path}[{i}]")
    elif a != b: out.append(f"{path}: {str(a)[:60]!r} vs {str(b)[:60]!r}")
    return out
